package ratelimit

import (
	"errors"
	"math"
	"sync"
	"time"
)

var ErrLimitExceeded = errors.New("ratelimit: limit exceeded")

type Bucket struct {
	mu       sync.Mutex
	tokens   float64
	capacity float64
	refill   float64
	last     time.Time
}

func New(capacity, refillPerSecond float64) *Bucket {
	return &Bucket{
		tokens:   capacity,
		capacity: capacity,
		refill:   refillPerSecond,
		last:     time.Now(),
	}
}

func (b *Bucket) Allow(n float64) error {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.advance(time.Now())
	if b.tokens < n {
		return ErrLimitExceeded
	}
	b.tokens -= n
	return nil
}

func (b *Bucket) advance(now time.Time) {
	elapsed := now.Sub(b.last).Seconds()
	b.tokens = math.Min(b.capacity, b.tokens+elapsed*b.refill)
	b.last = now
}
