export interface Range {
  start: number;
  end: number;
}

/**
 * Converts a duration in milliseconds to a human-readable string.
 *
 * Rounds to the nearest whole unit, so 1500ms renders as "2s" rather than
 * "1.5s". Callers needing precision should format the raw value themselves.
 *
 * @param ms - Duration in milliseconds. Negative values are treated as 0.
 * @returns A string like "2s", "5m", or "3h".
 */
export function formatDuration(ms: number): string {
  const s = Math.max(0, Math.round(ms / 1000));
  if (s < 60) return `${s}s`;
  if (s < 3600) return `${Math.round(s / 60)}m`;
  return `${Math.round(s / 3600)}h`;
}

/**
 * Parses an RFC 3339 timestamp into a Date.
 *
 * Parsing is delegated to the Date constructor, which is more lenient than
 * RFC 3339, so this does not validate the format: other strings Date accepts,
 * such as "2024", parse too.
 *
 * @param {string} input - An RFC 3339 string, with or without a timezone offset.
 * @returns {Date} The parsed Date.
 * @throws {RangeError} If the Date constructor cannot parse the string at all.
 */
export function parseTimestamp(input: string): Date {
  const d = new Date(input);
  if (Number.isNaN(d.getTime())) {
    throw new RangeError(`not an RFC 3339 timestamp: ${input}`);
  }
  return d;
}

export function nextRetryDelay(attempt: number, baseMs: number, capMs: number): number {
  const exp = Math.min(capMs, baseMs * 2 ** attempt);
  return Math.floor(Math.random() * exp);
}

/**
 * Returns true when the two ranges overlap at any point.
 *
 * Ranges are treated as half-open: [start, end). Two ranges that merely touch,
 * where one ends exactly where the other starts, do not overlap
 */
export function rangesOverlap(a: Range, b: Range): boolean {
  return a.start < b.end && b.start < a.end;
}
